ON CONFLICT (id) DO UPDATE SET
    label                = EXCLUDED.label,
    grupo_funcional       = EXCLUDED.grupo_funcional,
    descricao            = EXCLUDED.descricao,
    sinal_velocidade     = EXCLUDED.sinal_velocidade,
    sinal_aceleracao     = EXCLUDED.sinal_aceleracao,
    sinal_temperatura    = EXCLUDED.sinal_temperatura,
    componentes_internos = EXCLUDED.componentes_internos,
    modos_falha          = EXCLUDED.modos_falha,
    destacavel           = EXCLUDED.destacavel,
    inspecao             = EXCLUDED.inspecao,
    atualizado_em        = now();
